import random
import struct
import itertools

# Data type: arbitrary binary data
# Goal: Produce interesting but valid byte buffers for LZ4 fuzzers using FUZZ_PARAM_STR/FILENAME.
# Strategy: Compose buffers from patterns that exercise LZ4 well: highly compressible runs,
# repeating sequences > 64KB apart, mixed entropy regions, small/empty inputs, and sizes near
# internal thresholds. Keep total size <= 4096 bytes and within the fuzzer caps (mod 1500 etc.).

_MAX_TOTAL = 4096

def _rep(byte: int, count: int) -> bytes:
    return bytes([byte & 0xFF]) * max(0, count)

def _range_pattern(length: int, start: int = 0, step: int = 1) -> bytes:
    return bytes(((start + i * step) & 0xFF for i in range(max(0, length))))

def _random_bytes(rng: random.Random, length: int) -> bytes:
    return rng.randbytes(length) if hasattr(rng, 'randbytes') else bytes(rng.getrandbits(8) for _ in range(length))

def _repeat_block(block: bytes, total_len: int) -> bytes:
    if not block:
        return b""
    out = bytearray()
    while len(out) + len(block) <= total_len:
        out += block
    if len(out) < total_len:
        out += block[: total_len - len(out)]
    return bytes(out)

def _make_dictionary_like(rng: random.Random, size: int) -> bytes:
    # Typical LZ4 dictionaries benefit from repetitive/english-like/text-like content
    chunks = []
    # Common words and headers
    words = [b"the ", b"and ", b"LZ4", b"dictionary ", b"compress ", b"data ", b"AAAAA", b"\n", b";\n"]
    while sum(len(c) for c in chunks) < size:
        choice = rng.randint(0, 4)
        if choice == 0:
            w = rng.choice(words)
            rep = rng.randint(1, 50)
            chunks.append(w * rep)
        elif choice == 1:
            # numeric sequence
            l = rng.randint(8, 64)
            chunks.append(_range_pattern(l, start=rng.randint(0, 255), step=rng.choice([1, 3, 5, 7, 13])))
        elif choice == 2:
            # long run
            b = rng.randint(0, 255)
            chunks.append(_rep(b, rng.randint(32, 512)))
        else:
            # random noise block to break runs
            chunks.append(_random_bytes(rng, rng.randint(16, 128)))
    data = b"".join(chunks)
    return data[:size]

def _compose_sections(sections):
    out = bytearray()
    for part in sections:
        if not part:
            continue
        remaining = _MAX_TOTAL - len(out)
        if remaining <= 0:
            break
        out += part[:remaining]
    return bytes(out)

def _size_choices(rng: random.Random):
    # Favor sizes relevant to fuzz harness caps (they mod 1500, dicts mod ~70000 but our cap is 4096)
    interesting = [0, 1, 2, 3, 4, 7, 8, 15, 16, 31, 32, 63, 64, 127, 128, 255, 256, 511, 512, 1023, 1024, 1499]
    # Also some random sizes up to 2048
    interesting += [rng.randint(0, 2048) for _ in range(8)]
    # Ensure <= 4096
    return [min(x, _MAX_TOTAL) for x in interesting]

def _build_payload(rng: random.Random) -> bytes:
    size_opts = _size_choices(rng)

    # Choose a target total size
    total_target = rng.choice(size_opts + [rng.randint(0, 3000)])

    sections = []

    # 1) Highly compressible runs
    if rng.random() < 0.9:
        run_len = min(total_target // 4 + rng.randint(0, 64), 1500)
        sections.append(_rep(0x00, run_len))
        sections.append(_rep(0xFF, rng.randint(0, 256)))

    # 2) Repeating dictionary block to encourage matches > 64KB references are not possible in our cap,
    # but multiple repeated sequences still create good LZ4 matches
    dict_len = rng.choice([64, 256, 1024, 1500, rng.randint(32, 1536)])
    dict_block = _make_dictionary_like(rng, min(dict_len, 1500))
    if rng.random() < 0.8:
        sections.append(dict_block)
        if rng.random() < 0.7:
            sections.append(_repeat_block(dict_block, rng.randint(0, 1500)))

    # 3) Mixed entropy region
    if rng.random() < 0.8:
        mix_len = rng.choice(size_opts)
        chunk = bytearray()
        pos = 0
        while pos < mix_len:
            choice = rng.randint(0, 5)
            if choice <= 2:
                # small run
                run = rng.randint(1, 64)
                chunk += _rep(rng.randint(0, 255), min(run, mix_len - pos))
            elif choice == 3:
                # ascending pattern
                l = rng.randint(8, 128)
                chunk += _range_pattern(min(l, mix_len - pos), start=rng.randint(0, 255), step=1)
            elif choice == 4:
                # small dictionary snippet
                snip_len = min(rng.randint(8, 96), mix_len - pos)
                offs = rng.randint(0, max(0, len(dict_block) - 1)) if dict_block else 0
                chunk += dict_block[offs:offs+snip_len].ljust(snip_len, b'X')
            else:
                # noise
                l = rng.randint(8, 96)
                chunk += _random_bytes(rng, min(l, mix_len - pos))
            pos = len(chunk)
        sections.append(bytes(chunk))

    # 4) Edge mini-cases to trigger small or empty input paths
    if rng.random() < 0.5:
        sections.append(b"")
    if rng.random() < 0.5:
        sections.append(bytes([rng.randint(0, 255)]))

    # 5) Optional tail random noise
    if rng.random() < 0.6:
        tail = _random_bytes(rng, rng.randint(0, 256))
        sections.append(tail)

    data = _compose_sections(sections)

    # Trim or extend to the chosen total_target by adding a small random tail/prefix
    if len(data) > total_target:
        data = data[:total_target]
    elif len(data) < total_target:
        pad_len = min(total_target - len(data), 256)
        if pad_len > 0:
            # Prefer zeros to keep compressible
            if rng.random() < 0.7:
                data += _rep(0, pad_len)
            else:
                data += _random_bytes(rng, pad_len)

    return data[:_MAX_TOTAL]

def generate(seed: int) -> bytes:
    rng = random.Random(seed)

    # Choose among several scenario profiles to vary characteristics across calls
    profile = rng.randint(0, 5)

    if profile == 0:
        # All zeros or single-byte runs
        length = rng.choice([0, 1, 16, 64, 128, 512, 1024, 1499])
        b = rng.randint(0, 255)
        return _rep(b, length)
    elif profile == 1:
        # Pure dictionary-like text with repeats
        base = _make_dictionary_like(rng, rng.choice([64, 256, 1024, 1499]))
        repeat = _repeat_block(base, rng.randint(len(base), min(_MAX_TOTAL, len(base) * 3)))
        return repeat
    elif profile == 2:
        # High entropy random block with small compressible islands
        total = rng.randint(32, 2048)
        data = bytearray(_random_bytes(rng, total))
        # implant small runs
        for _ in range(rng.randint(1, 6)):
            pos = rng.randint(0, max(0, total - 16))
            run_len = rng.randint(8, 64)
            byte = rng.randint(0, 255)
            data[pos:pos+run_len] = _rep(byte, min(run_len, total - pos))
        return bytes(data)
    elif profile == 3:
        # Structured pattern: ascending bytes, then descending, then zeros
        a = _range_pattern(rng.randint(32, 1024), start=rng.randint(0, 255), step=1)
        b = bytes(reversed(a))
        c = _rep(0, rng.randint(0, 512))
        return (a + b + c)[:_MAX_TOTAL]
    elif profile == 4:
        # Small inputs around edge sizes
        size = rng.choice([0,1,2,3,4,7,8,15,16,31,32,63,64])
        # Alternate bytes and small runs
        data = bytearray()
        v = rng.randint(0, 255)
        for i in range(size):
            data.append((v + i) & 0xFF)
        if rng.random() < 0.5:
            data += _rep(v, rng.randint(0, 32))
        return bytes(data[:_MAX_TOTAL])
    else:
        # Mixed composite payload
        return _build_payload(rng)
